const exampleHolidayCalendar = new filescom.HolidayCalendar("example_holiday_calendar", {
    definition: {
        months: {
            "0": {
                calculatedRules: [{
                    name: "Good Friday",
                    "function": "easter(year)",
                    functionModifier: -2,
                }],
            },
            "1": {
                fixedRules: [{
                    name: "New Year's Day",
                    mday: 1,
                    observed: "to_weekday_if_weekend(date)",
                }],
                weekdayRules: [{
                    name: "Third Monday",
                    week: 3,
                    wday: 1,
                }],
            },
            "11": {
                weekdayRules: [{
                    name: "Thanksgiving",
                    week: 4,
                    wday: 4,
                }],
            },
            "12": {
                fixedRules: [{
                    name: "Christmas Eve Early Close",
                    mday: 24,
                    startTime: "13:00",
                    endTime: "17:00",
                    yearRanges: {
                        from: 2026,
                    },
                }],
            },
        },
    },
    name: "Company Holidays",
});
